CREATE TABLE cms_pages (id VARCHAR(120) PRIMARY KEY, slug VARCHAR(180) NOT NULL UNIQUE, title VARCHAR(240) NOT NULL, status VARCHAR(30) NOT NULL, current_version INT NOT NULL, version BIGINT NOT NULL DEFAULT 1, seo_json JSONB NOT NULL DEFAULT '{}'::jsonb, created_by VARCHAR(120) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE cms_page_versions (id VARCHAR(120) PRIMARY KEY, page_id VARCHAR(120) NOT NULL, version INT NOT NULL, content_json JSONB NOT NULL, content_hash CHAR(64) NOT NULL, created_by VARCHAR(120) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_by VARCHAR(120), published_at TIMESTAMPTZ, UNIQUE(page_id,version));
CREATE TABLE cms_schedules (id VARCHAR(120) PRIMARY KEY, page_id VARCHAR(120) NOT NULL, version INT NOT NULL, publish_at TIMESTAMPTZ, unpublish_at TIMESTAMPTZ, timezone VARCHAR(80) NOT NULL DEFAULT 'UTC', state VARCHAR(20) NOT NULL DEFAULT 'PENDING', processed_at TIMESTAMPTZ);
CREATE TABLE cms_outbox_events (id VARCHAR(120) PRIMARY KEY, aggregate_type VARCHAR(80) NOT NULL, aggregate_id VARCHAR(120) NOT NULL, event_type VARCHAR(120) NOT NULL, schema_version INT NOT NULL DEFAULT 1, occurred_at TIMESTAMPTZ NOT NULL, correlation_id VARCHAR(120) NOT NULL, payload_json JSONB NOT NULL, published_at TIMESTAMPTZ);
CREATE INDEX cms_page_status_idx ON cms_pages(status,updated_at DESC);
CREATE INDEX cms_schedule_due_idx ON cms_schedules(state,publish_at,unpublish_at);
